block.template:
{# Beispiel 4 · Ablauf: Liste mit Symbolfeld und Nummerierung über loop.index. #}
{% if title or block.editing %}<h2 class="steps__title" id="{{ block.title_id }}">{{ title }}</h2>{% endif %}
{% if intro or block.editing %}<p class="steps__intro">{{ intro }}</p>{% endif %}
<ol class="steps" role="list">
  {% for s in schritte %}
  <li class="step">
    <span class="step__badge" aria-hidden="true">{% if s.symbol %}{{ s.symbol | icon }}{% else %}{{ loop.index }}{% endif %}</span>
    <div class="step__body">
      <p class="step__count">{{ 'Schritt' | lt }} {{ loop.index }} {{ 'von' | lt }} {{ loop.length }}</p>
      <h3 class="step__title">{{ s.titel }}</h3>
      {% if s.text %}<p class="step__text">{{ s.text }}</p>{% endif %}
    </div>
  </li>
  {% endfor %}
</ol>

block.css:
.steps__title { margin: 0 0 .75rem; }
.steps__intro { max-width: 42rem; margin: 0 0 2rem; color: var(--cb-muted); }
.steps { display: grid; margin: 0; padding: 0; list-style: none; }
.step { position: relative; display: grid; grid-template-columns: 3rem 1fr; gap: 1rem; padding-bottom: 1.75rem; }
/* Verbindungslinie zwischen den Kreisen */
.step::before { content: ""; position: absolute; top: 3.25rem; bottom: .25rem; left: calc(1.5rem - 1px); width: 2px; background: var(--cb-line); }
.step:last-child { padding-bottom: 0; }
.step:last-child::before { display: none; }
.step__badge {
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background: var(--cb-accent);
  color: var(--cb-on-accent);
  font-size: 1.15rem;
  font-weight: 700;
}
.step__badge svg { width: 1.35rem; height: 1.35rem; }
.step__count { margin: .15rem 0 .1rem; color: var(--cb-muted); font-size: .8rem; letter-spacing: .05em; text-transform: uppercase; }
.step__title { margin: 0 0 .35rem; font-size: 1.2rem; }
.step__text { max-width: 42rem; margin: 0; }
@media (min-width: 60rem) {
  .steps { grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr)); gap: var(--cb-gap); }
  .step { grid-template-columns: 1fr; padding-bottom: 0; }
  .step::before { top: calc(1.5rem - 1px); bottom: auto; left: 3.75rem; right: .75rem; width: auto; height: 2px; }
}
